seed={(0,2),(1,0),(1,1),(2,0)}
def orientations(shape):
    result=[]
    for refl in [False,True]:
      s={(r,c if not refl else -c) for r,c in shape}
      for k in range(4):
        pts=list(s)
        for _ in range(k): pts=[(c,-r) for r,c in pts]
        mr=min(r for r,c in pts); mc=min(c for r,c in pts)
        norm=frozenset((r-mr,c-mc) for r,c in pts)
        if norm not in result:result.append(norm)
    return result
ors=orientations(seed)
